function totalWithTip(amount, rate) {
  if (!Number.isFinite(amount) || amount < 0 || !Number.isFinite(rate) || rate < 0) {
    throw new RangeError('Invalid input');
  }
  return amount * (1 + rate);
}
console.log(totalWithTip(100, 0.10)); // 110

const tasks = [{id:'a',done:false},{id:'b',done:true}];
function remaining(items){
  return items.filter(task => !task.done);
}
console.log(remaining(tasks)); // [{id:'a',done:false}]
